import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    adj = [set() for _ in range(N + 1)]

    for _ in range(M):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].add(v)
            adj[v].add(u)
        except StopIteration:
            break

    if N == 1:
        print(1)
        return

    def backtrack(current, visited_count, visited_mask):
        if visited_count == N:
            return True

        for neighbor in adj[current]:
            bit = 1 << neighbor
            if not (visited_mask & bit):
                if backtrack(neighbor, visited_count + 1, visited_mask | bit):
                    return True
        return False

    found = False
    for start in range(1, N + 1):
        if backtrack(start, 1, 1 << start):
            found = True
            break

    print(1 if found else 0)

if __name__ == "__main__":
    solve()
